mapper.select:
select a.FINPROD_ID finprodId, a.FINPROD_TYPE2 finprodType2, a.FINPROD_MARKET_ID finprodMarketId, a.FINPROD_NAME finprodName, a.FINPROD_ABBR finprodAbbr, a.CALENDAR_ID calendarId, a.IDATE idate, a.CCY ccy, a.VDATE vdate, a.MDATE mdate, a.TRADE_MARKET tradeMarket, b.TYPE_6 fundType, b.TYPE_7 secondType,
b.TYPE_9 type9, b.TYPE_10 type10, b.TYPE_11 type11, b.TYPE_12 type12,
c.IS_COMPOUND_INT isCompoundInt, d.CUSTOMER_NAME manager, f.PAY_TYPE divideMethod, f.PAY_CYCLE carryoverFreq,
(CASE WHEN C.PUR_SPEED is not null THEN CONCAT('T+',IFNULL( C.PUR_SPEED,'')) ELSE '' END) purSpeed, (CASE WHEN C.RED_SPEED is not null THEN CONCAT('T+',IFNULL( C.RED_SPEED,'')) ELSE '' END) redSpeed, c.TRM_FUND_TYPE trmFundType, c.TRM_FUND_ABBR trmFundAbbr from FIN_PRODUCT a left join MST_CUSTOMER_INFO d on d.CUSTOMER_ID = a.MANAGER left join FIN_CASH_INFO e on a.FINPROD_ID = e.FINPROD_ID and e.CASH_TYPE_2 = #{CASH_TYPE_2,jdbcType=VARCHAR} and e.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE,jdbcType=VARCHAR} left join FIN_CASH_PAY_RULE f on e.CASH_ID = f.CASH_ID and a.VDATE = f.EFF_DATE , FIN_PRODUCT_TYPE b , FIN_PRODUCT_ADD c where 1=1 and a.FINPROD_ID = b.FINPROD_ID and a.FINPROD_ID = c.FINPROD_ID and a.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and a.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
and a.CCY = #{ccy,jdbcType=VARCHAR}
and a.VDATE between #{sDate} and #{eDate}
and a.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
and a.MANAGER = #{manager,jdbcType=VARCHAR}
and b.TYPE_6 = #{fundType,jdbcType=VARCHAR}
AND b.TYPE_9 in
#{item}
AND b.TYPE_10 in
#{item}
AND b.TYPE_11 in
#{item}
and f.PAY_TYPE = #{divideMethod,jdbcType=VARCHAR}
and f.PAY_CYCLE = #{carryoverFreq,jdbcType=VARCHAR}
AND c.PUR_SPEED like concat(concat('%',#{purSpeed,jdbcType=VARCHAR}),'%')
AND c.RED_SPEED like concat(concat('%',#{redSpeed,jdbcType=VARCHAR}),'%')
AND c.TRM_FUND_TYPE in
#{item}
